        .await;

    let client = internal_client(&mock_server);
    let token = TokenValidationResult {
        user_id: 42,
        oauth_client_id: "client-1".to_string(),
        scopes: vec![],
        auth_strength: AuthStrength::Passwordless,
        auth_time: 0,
