    }

    pub async fn create_reminder(
        &self,
        payload: &serde_json::Value,
    ) -> Result<ReminderResponse, InternalError> {
        let mut url = self.api_base.clone();
        url.path_segments_mut()
            .map_err(|_| InternalError::Connection("api_base has impossible host".to_string()))?
            .extend(&["internal", "mcp", "reminders"]);
        url.set_query(Some(&format!("calendar_id={}", payload["calendar_id"])));

        let resp = self
            .http_client
            .post(url.as_str())
            .header("Content-Type", "application/json")
            .header("x-mcp-api-key", &self.api_key)
            .body(payload.to_string())
            .send()
            .await
            .map_err(|e| InternalError::Connection(e.to_string()))?;

        if !resp.status().is_success() {
            return Err(InternalError::Http(
                resp.status().as_u16(),
                "create_reminder failed".to_string(),
            ));
        }

        let body: String = resp
            .text()
            .await
            .map_err(|e| InternalError::Deserialize(e.to_string()))?;

        serde_json::from_str(&body)
            .map_err(|e| InternalError::Deserialize(format!("reminder response: {}", e)))
    }

    /// Resolve the single authoritative MCP grant for a user + OAuth client.
    ///
    /// CommonCal core is the source of truth for grants. The internal endpoint
    /// returns a vector; a well-formed response contains exactly one grant.
    /// Zero grants is a normal authorization outcome (`Ok(None)`); more than one
    /// is ambiguous core data and fails closed rather than selecting arbitrarily.
    pub async fn get_mcp_grant(
        &self,
        user_id: i64,
        client_id: &str,
    ) -> Result<Option<McpGrantResponse>, InternalError> {
        let mut url = self
            .api_base
            .join("internal/mcp/mcp-grants")
            .map_err(|e| InternalError::Connection(format!("failed to join URL: {}", e)))?;
        url.query_pairs_mut()
            .append_pair("user_id", &user_id.to_string())
            .append_pair("client_id", client_id);
        let resp = self
            .http_client
            .get(url.as_str())
            .header("x-mcp-api-key", &self.api_key)
            .send()
            .await
            .map_err(|e| InternalError::Connection(e.to_string()))?;

        if !resp.status().is_success() {
            return Err(InternalError::Http(
                resp.status().as_u16(),
                "get_mcp_grant failed".to_string(),
            ));
        }

        let grants = resp
            .json::<Vec<McpGrantResponse>>()
            .await
            .map_err(|e| InternalError::Deserialize(e.to_string()))?;

        match grants.len() {
            0 => Ok(None),
            1 => Ok(Some(grants.into_iter().next().unwrap())),
            _ => Err(InternalError::Http(
                500,
                "ambiguous grant response: expected at most one grant".to_string(),
            )),
        }
    }

    pub async fn check_idempotency(
        &self,
        operation_id: &str,
    ) -> Result<Option<serde_json::Value>, InternalError> {
        let url = self
            .api_base
            .join(&format!("internal/mcp/idempotency/{}", operation_id))
            .map_err(|e| InternalError::Connection(format!("failed to join URL: {}", e)))?;
        let resp = self
            .http_client
            .get(url.as_str())
            .header("x-mcp-api-key", &self.api_key)
            .send()
            .await
            .map_err(|e| InternalError::Connection(e.to_string()))?;

        if resp.status() == 404 {
            return Ok(None);
        }

        if !resp.status().is_success() {
            return Err(InternalError::Http(
                resp.status().as_u16(),
                "check_idempotency failed".to_string(),
            ));
        }

        let body: serde_json::Value = resp
            .json()
            .await
            .map_err(|e| InternalError::Deserialize(e.to_string()))?;

        Ok(Some(body))
    }

    pub async fn record_idempotency(
        &self,
        operation_id: &str,
        payload: &serde_json::Value,
    ) -> Result<(), InternalError> {
        let url = self
            .api_base
            .join("internal/mcp/idempotency")
            .map_err(|e| InternalError::Connection(format!("failed to join URL: {}", e)))?;
        let resp = self
            .http_client
            .post(url.as_str())
            .header("x-mcp-api-key", &self.api_key)
            .json(&serde_json::json!({
                "operation_id": operation_id,
                "payload": payload,
            }))
            .send()
            .await
            .map_err(|e| InternalError::Connection(e.to_string()))?;

        if !resp.status().is_success() {
            return Err(InternalError::Http(
                resp.status().as_u16(),
                "record_idempotency failed".to_string(),
            ));
        }

        Ok(())
    }
}

#[derive(Debug)]
pub enum InternalError {
    Connection(String),
    Http(u16, String),
    Deserialize(String),
}

impl std::fmt::Display for InternalError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Connection(msg) => write!(f, "connection error: {}", msg),
            Self::Http(code, msg) => write!(f, "http {}: {}", code, msg),
            Self::Deserialize(msg) => write!(f, "deserialize error: {}", msg),
        }
    }
}

impl std::error::Error for InternalError {}

